-- جزء 1 من 4 — نماذج modell-01–modell-02
-- مولّد من supabase/seed/b2.sql بـtools/split_seed.sh — لا تعدّله بالإيد
-- آمن للإعادة: شغّله مرتين ما بيغيّر شي.

begin;

-- مولّد من content/telc/b2 بـtools/export_sql.py — لا تعدّله بالإيد

insert into levels (id, title, sort, published, provider, stufe) values ('telc-b2', 'telc Deutsch B2', 0, true, 'telc', 'B2')
on conflict (id) do update set title = excluded.title,
  provider = coalesce(levels.provider, excluded.provider),
  stufe    = coalesce(levels.stufe,    excluded.stufe);

-- ================= modell-01 · ZUGANGSKONTROLLE =================
insert into tests (level_id, slug, title, subtitle, blocks, aufgaben, published, sort)
values ('telc-b2', 'modell-01', 'ZUGANGSKONTROLLE', '53 Aufgaben · 125 Minuten',
        '[{"id": "block-lesen", "parts": ["lv1", "lv2", "lv3", "lv4"], "title": "Lesen", "minutes": 45, "hint": "Aufgaben 1–18", "maxPoints": 54, "availablePoints": 54, "missing": 0}, {"id": "block-lesen-schreiben", "parts": ["lvs1", "lvs2"], "title": "Lesen und Schreiben", "minutes": 20, "hint": "Aufgaben 19–20 und Beschwerde", "maxPoints": 13, "availablePoints": 13, "missing": 0}, {"id": "block-hoeren", "parts": ["hv1", "hv2", "hv3", "hv4"], "title": "Hören", "minutes": 20, "hint": "Aufgaben 22–40", "maxPoints": 57, "availablePoints": 57, "missing": 0}, {"id": "block-hoeren-schreiben", "parts": ["hvs"], "title": "Hören und Schreiben", "minutes": 5, "hint": "Aufgabe 41 und Telefonnotiz", "maxPoints": 9, "availablePoints": 9, "missing": 0}, {"id": "block-sb", "parts": ["sb1", "sb2"], "title": "Sprachbausteine", "minutes": 35, "hint": "Aufgaben 46–57", "maxPoints": 6, "availablePoints": 6, "missing": 0}]'::jsonb, 53, true, 1)
on conflict (level_id, slug) do update set title = excluded.title, subtitle = excluded.subtitle, blocks = excluded.blocks, aufgaben = excluded.aufgaben, sort = excluded.sort;

insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Auf ins Abenteuer! Du hast Lust auf Sonne, Strand und eine fremde Sprache? Eine Sprachreise ermöglicht es dir, deine Sprachkenntnisse zu verbessern und gleichzeitig ein neues Land kennenzulernen."}, {"key": "B", "text": "Global Career Network: Internationale Stellenangebote für Akademiker und Führungskräfte weltweit. Finden Sie anspruchsvolle Positionen in Forschung, Lehre und Industrie."}, {"key": "C", "text": "Sprachenschule Lingua: Staatlich anerkannte Ausbildung zum Fremdsprachenkorrespondenten oder Übersetzer. Jetzt informieren und durchstarten!"}, {"key": "D", "text": "Existenzgründung leicht gemacht: Ihr Weg in die Selbstständigkeit. Beratung, Seminare und Fördermittel für angehende Unternehmerinnen und Unternehmer."}, {"key": "E", "text": "Knigge im Berufsalltag: Der richtige Umgangston unter Kollegen und Vorgesetzten. Praxistipps für ein souveränes Auftreten im Betrieb."}, {"key": "F", "text": "Erfolgreich bewerben: Professionelle Bewerbungsunterlagen und Coaching für Vorstellungsgespräche."}, {"key": "G", "text": "Auslandspraktika weltweit: Erste Berufserfahrungen sammeln, internationale Kontakte knüpfen und Fremdsprachenkenntnisse vertiefen. Für Studierende und Berufseinsteiger."}, {"key": "H", "text": "Arbeitsrecht aktuell: Kündigung erhalten? Wir prüfen Ihre Kündigung und unterstützen Sie bei der Kündigungsschutzklage. Kostenlose Ersteinschätzung."}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 12, 'Lesen Sie den Text und die Aufgaben 6–9. Entscheiden Sie, welche Lösung richtig ist.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Zugangskontrolle und Zeiterfassung", "b": true}, {"t": "Als Mitarbeiterinnen und Mitarbeiter erhalten Sie zu Beginn Ihres Arbeitsverhältnisses einen Firmenausweis mit Chip-Karte. Dieser berechtigt zum Zugang in das Unternehmensgebäude und dient gleichzeitig zur Erfassung der Arbeitszeit. Außerdem können Sie mit Ihrem Firmenausweis in der Kantine und am Getränkeautomaten bezahlen und das hauseigene Fitnessstudio benutzen.", "b": false}, {"t": "Neben den Aufzügen im Erdgeschoss finden Sie ein digitales Zeiterfassungsgerät. Bitte halten Sie beim Betreten und Verlassen des Gebäudes Ihren Firmenausweis an die blau markierte Fläche. Das Gerät registriert Ihre Anwesenheit automatisch. Sollten Sie Ihren Ausweis einmal vergessen haben, wenden Sie sich bitte unverzüglich an den Empfang.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Forumsbeiträge a–f. Welcher Beitrag passt zu welcher Situation? Wenn kein Beitrag passt, wählen Sie X.', 'matching', '{"bank": [{"key": "A", "text": "Günther: Das kann man pauschal gar nicht so sagen. Wie das in deinem Unternehmen geregelt ist, steht in deinem Arbeitsvertrag. Ab wann du eine Arbeitsunfähigkeitsbescheinigung brauchst, findest du meistens unter den Paragraphen „Arbeitsverhinderung\" oder „Krankheit\"."}, {"key": "B", "text": "Marion: Nein, vorher musst du erst mal eine Abmahnung bekommen. Wenn du dann allerdings noch mal fehlst, ohne Bescheid zu sagen, musst du mit der Kündigung rechnen. Such doch noch mal das Gespräch mit deinem Chef. Ihr findet bestimmt eine Lösung."}, {"key": "C", "text": "Karin: Du kannst nicht einfach kommen und gehen, wann du willst, auch wenn du die Absicht hattest, die versäumte Zeit nachzuholen. Die Arbeitszeiten sind ja vertraglich geregelt. Wenn sich Mitarbeiter nicht daran halten, ist eine Abmahnung vor der Kündigung nicht notwendig."}, {"key": "D", "text": "Elli: Wie du selbst schreibst, können im Krankheitsfall die Urlaubstage auf dein Urlaubskonto zurückgebucht werden. Du brauchst natürlich ein ärztliches Attest. Das gilt allerdings nicht, wenn du dich um ein krankes Kind kümmern musst. In diesem Fall gelten die Urlaubstage als genommen."}, {"key": "E", "text": "Sabine: Diese Situation kennen doch alle Eltern. Wenn ich für meinen Sohn mal keine Betreuung finde, kann ich ihn auch ausnahmsweise mit ins Büro nehmen. Meine Chefin ist da zum Glück sehr verständnisvoll."}, {"key": "F", "text": "Jorge: Also ich gehe immer gleich am ersten Krankheitstag zum Arzt. Sicher ist sicher. Außerdem kann es nicht schaden, wenn dich ein Doktor anschaut, wenn du dich nicht wohlfühlst. Gerade wenn du Kinder hast, ist es wichtig, dass du weißt, was dir fehlt. Du willst ja niemanden anstecken."}, {"key": "X", "text": "Kein Beitrag passt."}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 13, 'Lesen Sie das Protokoll und die Aufgaben 14–18. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll der Abteilungsleiterbesprechung vom 20.06.20XX", "b": true}, {"t": "Konrad-Adenauer-Straße 43, 30159 Hannover, Besprechungsraum: 032", "b": false}, {"t": "Teilnehmende: Veronika Emmerich (VE, Stellvertreterin Geschäftsleitung), Marita Hinze (MH, Leitung Einkauf), Peter Renner (PR, Leitung Produktion), Thomas Hagen (TH, Leitung Finanzen), Sibylle Marquardt (SM, Leitung Personal), Christian Werner (CW, Leitung Vertrieb), Jessica Froh (JF, Leitung Marketing), Jutta Raulin (JR, Leitung Qualitätssicherung), Joachim Meyer (JM, Leitung IT)", "b": false}, {"t": "Sitzungsleitung: Veronika Emmerich. Protokollantin: Sibylle Marquardt. Nicht Anwesende: Martin Stahl (MS, Geschäftsleitung).", "b": false}, {"t": "TOP 1 Begrüßung und Genehmigung der Tagesordnungspunkte: Einstimmig angenommen. Nächster Besprechungstermin: 24.09.20XX nach der Urlaubszeit.", "b": false}, {"t": "TOP 2 Probleme mit einem Zulieferer: MH berichtet, dass unser südamerikanischer Zulieferer Dos Caminos Exports Ltd. die Preise für seine Vorprodukte ohne Absprache erhöht hat. Nach intensivem Schriftwechsel kam es zu einer Einigung: Bis zum 31. des kommenden Monats wird ein günstigerer Zulieferer gesucht (zuständig: MH und TH, evtl. asiatischer Raum). Ziel ist der beidseitige Rücktritt vom Vertrag ohne weitere Ansprüche.", "b": false}, {"t": "TOP 3 Zwischenstand Qualitätssicherung: JR berichtet, dass das neue Konzept für Qualitätsprüfung bereits bei 30% Abweichung eine Fehlermeldung ausgibt. Die Reklamationen sind signifikant zurückgegangen.", "b": false}, {"t": "TOP 4 Neue Überstundenregelung: VE dankt für die Bereitschaft zu Überstunden. Bis zu 20 Überstunden pro Quartal werden ab sofort ausschließlich vergütet und können aus personellen Gründen vorerst nicht als Freizeit genommen werden. Genehmigt vom Betriebsrat am 15.06.20XX.", "b": false}, {"t": "TOP 5 Private Nutzung der Dienstwagen: SM teilt mit, dass Dienstwagen ab nächstem Monat auch privat genutzt werden dürfen. Voraussetzung ist ein monatlich einzureichendes Fahrtenbuch mit Angabe der privat gefahrenen Kilometer.", "b": false}, {"t": "TOP 6 Sonstiges: Bowlingabend in zwei Wochen in der Anlage „Sport und Spaß“, Anmeldung im Intranet bis Freitag nächster Woche.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19–20. Welche Lösung ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Beschwerde über Putzdienst / Reinigung", "b": true}, {"t": "Sehr geehrte Frau Woller, leider muss ich mich heute mit einer Beschwerde an Sie wenden. Wir haben einen Vertrag mit Ihrer Firma für die Reinigung unserer Büroräume. In diesem Vertrag sind täglich 3 Stunden Arbeit bei uns festgelegt, und zwar von 6.00 Uhr bis 9.00 Uhr morgens. In den letzten zwei Wochen war unsere Sekretärin einige Male bereits vor 9 Uhr im Büro, von Ihrem Putzdienst war aber niemand zu sehen. Wie kann das sein? Wenn wir 3 Stunden bezahlen, erwarten wir auch, dass Ihr Personal drei Stunden bei uns arbeitet. Wenn Sie für die Reinigung unserer Räume weniger als die vereinbarte Zeit benötigen, sollten Sie uns darüber informieren, damit wir den Vertrag ändern. Ich bitte um umgehende Stellungnahme und natürlich die Angleichung der Rechnung an die tatsächlich geleisteten Arbeitsstunden. Mit freundlichen Grüßen, Theo Lassner.", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf die Beschwerde.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrer Vorgesetzten:", "b": true}, {"t": "Hallo Friederike, gerade habe ich die Mail von der Firma Huber GmbH gelesen. Ich verstehe den Ärger von Herrn Lassner. Bitte sprich mal mit unseren Leuten und kläre, was da los ist, und antworte dann Herrn Lassner. Es ist ganz wichtig, dass du ihm zusagst, dass so etwas nie wieder vorkommen wird. Gib ihm auch einen Rabatt auf die nächste Rechnung in Höhe von 20 %. Wir dürfen die Firma mit diesem großen Auftrag keinesfalls als Kunden verlieren. Gruß, Heike.", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Aussagen. Welche Aussage a–f passt zu welcher Person 28–31?', 'matching', '{"bank": [{"key": "A", "text": "Mitarbeiter sollten ihr Diensthandy nach der Arbeit ausschalten."}, {"key": "B", "text": "Im Urlaub sollte man sich mit Arbeitsangelegenheiten nicht beschäftigen."}, {"key": "C", "text": "Arbeit und Freizeit sollten klar getrennt sein, um das Privatleben zu schützen."}, {"key": "D", "text": "Für manche Kunden ist es wichtig, dass der Kundenservice auch am Wochenende verfügbar ist."}, {"key": "E", "text": "Man sollte das Privatleben respektieren und Arbeitsanfragen außerhalb der Arbeitszeit vermeiden."}, {"key": "F", "text": "Manche Mitarbeiter sind bereit, für den Kundenservice am Wochenende erreichbar zu sein."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 5, 'Sie hören einen Vortrag. Wählen Sie für die Aufgaben 32–35 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 4, 'Sie hören fünf Ansagen auf der Mailbox. Wählen Sie für die Aufgaben 36–40 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben, Telefonnotiz', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Autovermietung Klein", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Adriane Schmid (Autovermietung Klein):", "b": false}, {"t": "„Guten Tag, hier spricht Adriane Schmid von der Autovermietung Klein. Sie haben angerufen und um ein Angebot gebeten. Ich kann Ihnen dieses Mal einen Mittelklassewagen für Sie zum Sonderpreis von 99 Euro pro Tag anbieten. Sie können das Auto vollgetankt wieder abgeben oder wir machen das kostenpflichtig für Sie. Außerdem müssen Sie mit uns die Versicherung regeln. Bitte rufen Sie mich zurück und sagen Sie mir, ob Sie das Angebot so annehmen. Telefon 0173 721 572 6.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–h passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "BESTIMMT"}, {"key": "B", "text": "DA"}, {"key": "C", "text": "DAMIT"}, {"key": "D", "text": "FÜR"}, {"key": "E", "text": "SICHER"}, {"key": "F", "text": "SONDERN"}, {"key": "G", "text": "UM"}, {"key": "H", "text": "ÜBER"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Bewerbung um ein Praktikum", "b": true}, {"t": "Sehr geehrte Damen und Herren,", "b": false}, {"t": "zunächst bedanke ich mich für das freundliche, informative Telefonat. Wie besprochen übersende ich Ihnen meine Bewerbungsunterlagen. Auf Ihrer Homepage habe ich mich bereits über das Ausbildungskonzept Ihrer Hotelkette informiert und bin (46), in Ihrem Haus vielfältige Einblicke in die Arbeit eines Hotelkaufmannes erhalten zu können.", "b": false}, {"t": "Ich arbeite sehr gerne mit Menschen zusammen. Teamfähigkeit und Flexibilität bringe ich als Voraussetzung mit und interessiere mich (47) die Abläufe in der Hotelverwaltung. Ein Praktikum in der Hotelbranche möchte ich deshalb absolvieren, (48) ich nicht nur im Umgang mit Menschen, (49) auch im Planen und Organisieren meine großen Stärken sehe.", "b": false}, {"t": "Ich erwarte von diesem Praktikum, mein theoretisches Wissen durch praktische Erfahrung weiter vertiefen zu können, (50) mir dann mit meiner Berufswahl endgültig sicher zu sein. (51) überzeuge ich Sie in einem persönlichen Gespräch. Über eine Einladung würde ich mich sehr freuen.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Alexander Thiel", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Stornierung des Auftrages mit Nr. RB 2876/20", "b": true}, {"t": "Sehr geehrte Damen und Herren,", "b": false}, {"t": "nach dem Besuch Ihres Vertriebsmitarbeiters entschieden wir uns für (52) von zwei Kaffeevollautomaten für unsere Krankenhauskantine.", "b": false}, {"t": "Unsere Auftragserteilung erfolgte in KW 12. Wir (53) eine Auftragsbestätigung mit Liefertermin in KW 16.", "b": false}, {"t": "(54) der Lieferfrist haben wir Sie telefonisch mehrmals eindringlich darauf hingewiesen, dass wir die Maschinen dringend benötigen.", "b": false}, {"t": "(55) wir uns in KW 18 und haben die Lieferung immer noch nicht erhalten.", "b": false}, {"t": "Wir räumen Ihnen letztmalig eine Lieferfrist bis Ablauf der KW 20 ein. Sollte die Ware bis dahin (56) sein, machen wir von unserem Widerrufsrecht Gebrauch und stornieren unsere Bestellung. Wir bitten um Ihr Verständnis.", "b": false}, {"t": "Bitte schicken Sie uns umgehend eine (57).", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Eva Al Hossan", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-01'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Moutasem fragt sich, wie er neue Kollegen korrekt ansprechen sollte.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Selma wurde entlassen und will sich dagegen wehren.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Anka überlegt, eine Ausbildung im Fremdsprachenbereich zu machen.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Sean ist Professor für Biologie und sucht einen Job im internationalen Umfeld.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Yassin möchte erste Berufserfahrungen im Ausland sammeln.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Der Firmenausweis dient ausschließlich zur Erfassung der Arbeitszeit.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'Das Zeiterfassungsgerät befindet sich im Erdgeschoss neben den Aufzügen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Mit dem Firmenausweis kann man', '[{"key": "A", "text": "das Fitnessstudio kostenlos nutzen."}, {"key": "B", "text": "in der Kantine bargeldlos bezahlen."}, {"key": "C", "text": "Rabatte im Supermarkt erhalten."}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Bei Verlust oder Vergessen des Ausweises', '[{"key": "A", "text": "muss man sofort nach Hause fahren."}, {"key": "B", "text": "wendet man sich an den Empfang."}, {"key": "C", "text": "wird das Gehalt gekürzt."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Gabi: Ich hatte gerade Urlaub und gleich am ersten Urlaubstag wurde meine Kleine krank und ich musste sie vier Tage lang pflegen. Wenn ich im Urlaub krank werde, kann ich die Tage zurückbekommen. Aber wie ist das, wenn das Kind krank wird?', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Charlotte: Ich konnte leider mal wieder nicht zur Arbeit gehen, weil mein Kind krank war. Als ich heute angerufen habe, hat mein Chef total überzogen reagiert und mir mit Kündigung gedroht, wenn ich mehr als einen Tag fehle. Das geht doch nicht, oder?', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Lars: Ich bin letzten Montag mit furchtbaren Kopfschmerzen aufgewacht und konnte nicht aufstehen. Leider habe ich vergessen, meinen Arbeitgeber anzurufen, und bin im Bett geblieben. Jetzt will mein Chef mir kündigen, weil ich unentschuldigt gefehlt habe. Geht das so einfach?', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Kamil: Gestern war ich krank. Als ich heute wieder im Büro war, wollte mein Chef direkt die Krankschreibung haben. Ich war immer der Meinung, die braucht man erst nach drei Tagen?', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Der Termin der nächsten Sitzung', '[{"key": "A", "text": "findet nach Abstimmung im Herbst statt."}, {"key": "B", "text": "muss verlegt werden."}, {"key": "C", "text": "wird noch bekannt gegeben."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Die Firma', '[{"key": "A", "text": "hat ohne Weiteres die Preiserhöhung des Zulieferers akzeptiert."}, {"key": "B", "text": "will sich an den höheren Transportkosten gern beteiligen."}, {"key": "C", "text": "wird einen neuen Vertragspartner suchen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Die Abteilung Qualitätssicherung', '[{"key": "A", "text": "berichtet von 30 Prozent fehlerhafter Produkte."}, {"key": "B", "text": "hat keine Qualitätsprobleme."}, {"key": "C", "text": "verzeichnet erste Erfolge."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'Die Mitarbeitenden', '[{"key": "A", "text": "haben mit dem Betriebsrat gesprochen."}, {"key": "B", "text": "können alle Überstunden als Freizeit nehmen."}, {"key": "C", "text": "müssen zurzeit Mehrarbeit leisten."}]'::jsonb, 3, null::jsonb, 3),
    ('lv4', '18', 'Das Fahrtenbuch', '[{"key": "A", "text": "dokumentiert alle gefahrenen Kilometer."}, {"key": "B", "text": "enthält nichtdienstliche Autofahrten."}, {"key": "C", "text": "wird von allen Mitarbeitern geführt."}]'::jsonb, 3, null::jsonb, 4),
    ('lvs1', '19', 'Herr Lassner', '[{"key": "A", "text": "möchte seine Rechnung nicht begleichen."}, {"key": "B", "text": "ist mit der Sauberkeit im Büro nicht zufrieden."}, {"key": "C", "text": "will nur die geleisteten Stunden bezahlen."}]'::jsonb, 3, null::jsonb, 0),
    ('lvs1', '20', 'Der Putzdienst', '[{"key": "A", "text": "hält die Arbeitszeit nicht ein."}, {"key": "B", "text": "hat zu wenig Zeit."}, {"key": "C", "text": "möchte einen neuen Vertrag."}]'::jsonb, 3, null::jsonb, 1),
    ('lvs2', 'B', 'Antworten Sie Herrn Lassner auf seine Beschwerde im Namen von Friederike Baumann.', null::jsonb, 0, '{"points": ["Entschuldigung und Bedauern über die Unannehmlichkeiten", "Erklärung des Problems nach Rücksprache mit dem Personal", "Zusicherung, dass dies nicht wieder vorkommen wird", "Angebot eines Rabatts von 20 % auf die nächste Rechnung"]}'::jsonb, 0),
    ('hv1', '22', 'In der Spätschicht ist ein Fahrer von Mittwoch bis Samstag ausgefallen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('hv1', '23', 'Zarif', '[{"key": "A", "text": "arbeitet regelmäßig in der Spätschicht."}, {"key": "B", "text": "kann am Mittwoch einspringen."}, {"key": "C", "text": "möchte Doppelschichten machen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv1', '24', 'Frau Li von Cargo KG möchte Holztüren umtauschen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('hv1', '25', 'Frau Li möchte', '[{"key": "A", "text": "Türen, die viel Licht durchlassen, bei denen die Privatsphäre der Mitarbeitenden trotzdem nicht verletzt wird."}, {"key": "B", "text": "helle Türen für den Eingangsbereich."}, {"key": "C", "text": "verschiedene Modelle als Muster bekommen."}]'::jsonb, 3, null::jsonb, 3),
    ('hv1', '26', 'Das Restaurant „Vier Jahreszeiten“ hat sich über fehlerhafte Lieferungen beschwert.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 4),
    ('hv1', '27', 'Geliefert wurde', '[{"key": "A", "text": "ein Gasherd statt eines Elektroherds."}, {"key": "B", "text": "ein Elektroherd statt eines Gasherds und ein zu schmaler Geschirrspüler."}, {"key": "C", "text": "ein zu breiter Geschirrspüler."}]'::jsonb, 3, null::jsonb, 5),
    ('hv2', '28', 'Person 1', null::jsonb, 3, null::jsonb, 0),
    ('hv2', '29', 'Person 2', null::jsonb, 3, null::jsonb, 1),
    ('hv2', '30', 'Person 3', null::jsonb, 3, null::jsonb, 2),
    ('hv2', '31', 'Person 4', null::jsonb, 3, null::jsonb, 3),
    ('hv3', '32', 'Die Firma hat zurzeit', '[{"key": "A", "text": "mehr Ersthelfer als gesetzlich vorgeschrieben."}, {"key": "B", "text": "so viele Ersthelfer wie gesetzlich vorgeschrieben."}, {"key": "C", "text": "weniger Ersthelfer als gesetzlich vorgeschrieben."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'Die Ausbildung zum Ersthelfer', '[{"key": "A", "text": "ist kostenfrei."}, {"key": "B", "text": "ist nur beim Malteser Hilfsdienst erlaubt."}, {"key": "C", "text": "zählt voll zur Arbeitszeit."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Wer sich anmelden möchte,', '[{"key": "A", "text": "kann sich an das Personalbüro wenden."}, {"key": "B", "text": "muss dem Arbeitgeber eine Bescheinigung vorlegen."}, {"key": "C", "text": "sollte dies spätestens zwei Wochen vor Kursbeginn tun."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Murat', '[{"key": "A", "text": "kann ohne Lehrgang Ersthelfer werden, wenn er sein Ausbildungszeugnis vorlegt."}, {"key": "B", "text": "muss den kompletten Erste-Hilfe-Kurs wiederholen."}, {"key": "C", "text": "darf auf keinen Fall als Ersthelfer arbeiten."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Andrea', '[{"key": "A", "text": "kann den geplanten Termin nicht einhalten."}, {"key": "B", "text": "möchte sich Montag wieder melden."}, {"key": "C", "text": "trifft einen Vertreter zum Arbeitsfrühstück."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Frau Plassberg', '[{"key": "A", "text": "möchte eine Steuerprüfung auswerten."}, {"key": "B", "text": "möchte die neue Werbekampagne diskutieren."}, {"key": "C", "text": "möchte über die Dienstreise sprechen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Daniela Schöller', '[{"key": "A", "text": "bittet um heutige Abholung der Ware."}, {"key": "B", "text": "braucht die Lieferung dringend."}, {"key": "C", "text": "hat den Eilzuschlag bezahlt."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Herr Lattermann', '[{"key": "A", "text": "bekommt eine Maschine aus Hamburg."}, {"key": "B", "text": "bestätigt den Empfang der Maschine."}, {"key": "C", "text": "liefert eine Maschine nach Dresden."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Frau Bernhardt', '[{"key": "A", "text": "hat Änderungswünsche für die Homepage."}, {"key": "B", "text": "meldet sich bei ihrer Sekretärin."}, {"key": "C", "text": "möchte die Garantie verlängern."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie die Kundenanfrage:', null::jsonb, 0, '{"points": ["Anruferin und Firma (Adriane Schmid, Autovermietung Klein)", "Rückrufnummer (0173 721 572 6)", "Einzelheiten des Angebots (Mittelklassewagen für 99 Euro pro Tag)", "Bedingungen (Vollgetankt abgeben oder kostenpflichtig, Versicherung regeln)", "Zu erledigen (Rückruf, ob das Angebot angenommen wird)"]}'::jsonb, 0),
    ('sb1', '46', '… Ausbildungskonzept Ihrer Hotelkette informiert und bin (46), in Ihrem Haus vielfältige Einblicke in die …', null::jsonb, 0.5, null::jsonb, 0),
    ('sb1', '47', '… Voraussetzung mit und interessiere mich (47) die Abläufe in der Hotelverwaltung. Ein Praktikum in der …', null::jsonb, 0.5, null::jsonb, 1),
    ('sb1', '48', '… Hotelbranche möchte ich deshalb absolvieren, (48) ich nicht nur im Umgang mit Menschen, …', null::jsonb, 0.5, null::jsonb, 2),
    ('sb1', '49', '… ich nicht nur im Umgang mit Menschen, (49) auch im Planen und Organisieren meine großen …', null::jsonb, 0.5, null::jsonb, 3),
    ('sb1', '50', '… praktische Erfahrung weiter vertiefen zu können, (50) mir dann mit meiner Berufswahl endgültig sicher zu …', null::jsonb, 0.5, null::jsonb, 4),
    ('sb1', '51', '… Berufswahl endgültig sicher zu sein. (51) überzeuge ich Sie in einem persönlichen Gespräch. Über eine …', null::jsonb, 0.5, null::jsonb, 5),
    ('sb2', '52', '… Vertriebsmitarbeiters entschieden wir uns für (52) von zwei Kaffeevollautomaten für unsere Krankenhauskantine. …', '[{"key": "A", "text": "einen Auftrag"}, {"key": "B", "text": "eine Bestellung"}, {"key": "C", "text": "eine Anforderung"}]'::jsonb, 0.5, null::jsonb, 0),
    ('sb2', '53', '… Auftragserteilung erfolgte in KW 12. Wir (53) eine Auftragsbestätigung mit Liefertermin in KW 16. …', '[{"key": "A", "text": "bekommen danach"}, {"key": "B", "text": "bestellten dann"}, {"key": "C", "text": "erhielten daraufhin"}]'::jsonb, 0.5, null::jsonb, 1),
    ('sb2', '54', '… Liefertermin in KW 16. (54) der Lieferfrist haben wir Sie telefonisch mehrmals …', '[{"key": "A", "text": "Vor Beginn"}, {"key": "B", "text": "Nach Ablauf"}, {"key": "C", "text": "Während"}]'::jsonb, 0.5, null::jsonb, 2),
    ('sb2', '55', '… dringend benötigen. (55) wir uns in KW 18 und haben die Lieferung immer noch nicht erhalten. …', '[{"key": "A", "text": "Mittlerweile befinden"}, {"key": "B", "text": "Früher waren"}, {"key": "C", "text": "Bald sind"}]'::jsonb, 0.5, null::jsonb, 3),
    ('sb2', '56', '… Sollte die Ware bis dahin (56) sein, machen wir von unserem Widerrufsrecht Gebrauch …', '[{"key": "A", "text": "nicht eingetroffen"}, {"key": "B", "text": "beschädigt geliefert"}, {"key": "C", "text": "zurückgeschickt"}]'::jsonb, 0.5, null::jsonb, 4),
    ('sb2', '57', '… Bitte schicken Sie uns umgehend eine (57). Mit freundlichen Grüßen Eva Al Hossan', '[{"key": "A", "text": "telefonische Zusage"}, {"key": "B", "text": "neue Rechnung"}, {"key": "C", "text": "schriftliche Stellungnahme"}]'::jsonb, 0.5, null::jsonb, 5)
) as v(section_id, item_id, text, options, points, meta, sort)
